**LinkedList Library in C++**
=====================================

This library provides a basic implementation of a singly linked list in C++. It includes functions for common operations such as inserting, deleting, and traversing the list.

**LinkedList.h**
---------------

```cpp
#ifndef LINKED_LIST_H
#define LINKED_LIST_H

class Node {
public:
    int data;
    Node* next;

    Node(int value) : data(value), next(nullptr) {}
};

class LinkedList {
private:
    Node* head;

public:
    LinkedList() : head(nullptr) {}

    ~LinkedList() {
        while (head!= nullptr) {
            Node* temp = head;
            head = head->next;
            delete temp;
        }
    }

    void insert(int value);
    void deleteNode(int value);
    void printList();
    void reverseList();
    int length();
    int search(int value);
};

#endif // LINKED_LIST_H
```

**LinkedList.cpp**
-----------------

```cpp
#include "LinkedList.h"
#include <iostream>

void LinkedList::insert(int value) {
    Node* newNode = new Node(value);

    if (head == nullptr) {
        head = newNode;
    } else {
        Node* temp = head;
        while (temp->next!= nullptr) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
}

void LinkedList::deleteNode(int value) {
    if (head == nullptr) return;

    if (head->data == value) {
        Node* temp = head;
        head = head->next;
        delete temp;
        return;
    }

    Node* temp = head;
    while (temp->next!= nullptr) {
        if (temp->next->data == value) {
            Node* nodeToDelete = temp->next;
            temp->next = temp->next->next;
            delete nodeToDelete;
            return;
        }
        temp = temp->next;
    }
}

