Here's a simple question-answering system in Python using a dictionary to store the questions and their corresponding answers.

### Question-Answering System Code
```python
class QuestionAnsweringSystem:
    def __init__(self):
        self.questions = {
            "What is the capital of France?": "Paris",
            "Who is the CEO of Tesla?": "Elon Musk",
            "What is the largest planet in our solar system?": "Jupiter",
            # Add more questions and answers here...
        }

    def answer_question(self, question):
        """Returns the answer to the given question."""
        question = question.lower()
        for q, a in self.questions.items():
            if q.lower() == question:
                return a
        return "Sorry, I don't know the answer to that."

    def add_question(self, question, answer):
        """Adds a new question and answer to the system."""
        self.questions[question] = answer

    def display_questions(self):
        """Displays all the questions in the system."""
        for question in self.questions.keys():
            print(question)

def main():
    qa_system = QuestionAnsweringSystem()

    while True:
        print("\nQuestion-Answering System Menu:")
        print("1. Ask a question")
        print("2. Add a new question")
        print("3. Display all questions")
        print("4. Quit")

        choice = input("Enter your choice: ")

        if choice == "1":
            question = input("Enter your question: ")
            print(qa_system.answer_question(question))
        elif choice == "2":
            question = input("Enter the question: ")
            answer = input("Enter the answer: ")
            qa_system.add_question(question, answer)
            print("Question added successfully!")
        elif choice == "3":
            qa_system.display_questions()
        elif choice == "4":
            break
        else:
            print("Invalid choice. Please try again.")

if __name__ == "__main__":
    main()
```

